{
  "sql": "SELECT t.categoria_ingles, mala_calificacion, porcentaje_retrasos FROM ( SELECT AVG(review_score) AS promedio_global FROM vw_entregas_retrasos ) g JOIN ( SELECT t2.product_category_name_english AS categoria_ingles, AVG(review_score) AS mala_calificacion, SUM(CASE WHEN entrega_con_retraso = 1 THEN 1 ELSE 0 END) * 1.0 / COUNT(*) AS porcentaje_retrasos FROM vw_entregas_retrasos o JOIN order_items oi ON o.order_id = oi.order_id JOIN products p ON oi.product_id = p.product_id LEFT JOIN product_category_translation t2 ON p.product_category_name = t2.product_category_name WHERE p.product_category_name_english IS NOT NULL GROUP BY categoria_ingles ) t ON t.mala_calificacion < g.promedio_global AND t.porcentaje_retrasos < (SELECT AVG(porcentaje_retrasos) FROM ( SELECT SUM(CASE WHEN entrega_con_retraso = 1 THEN 1 ELSE 0 END) * 1.0 / COUNT(*) AS porcentaje_retrasos FROM vw_entregas_retrasos ) )"
}
